20	/** ALU operation codes. */
21	object AluOp extends ChiselEnum {
22	  val NOP, ADD, ADDI, SUB, AND, ANDI, OR, ORI, XOR, XORI,
23	      SLL, SLLI, SRL, SRLI, SRA, SRAI,
24	      SLT, SLTI, SLTU, SLTIU,
25	      LW, LH, LB, LHU, LBU,
26	      SW, SH, SB,
27	      BEQ, BNE, BLT, BGE, BLTU, BGEU,
28	      AUIPC, LUI, JAL, JALR,
29	      FENCE,
30	      // Bitmanip (Zbb) extensions
31	      SEXTB, SEXTH, ZEXTH,
32	      CLZ, CTZ, CPOP,
33	      ORCB, REV8,
34	      XNOR, ORN, ANDN,
35	      MAX, MAXU, MIN, MINU,
36	      ROL, ROR,
37	      RORI,
38	      // CSR ops (encoded as ALU ops)
39	      ECALL, EBREAK, MRET, WFI = Value
40	}
41	
42	/** Arithmetic Logic Unit for the scalar core.
43	  *
44	  * Pipeline: inputs are latched on the clock edge and output is
45	  * available one cycle later.
46	  */
47	class Alu(p: Parameters) extends Module {
48	  val addrWidth = log2Ceil(p.nRegs)
49	
50	  val io = IO(new Bundle {
51	    val req = Flipped(Valid(new Bundle {
52	      val addr = UInt(addrWidth.W)
53	      val op   = AluOp()
54	    }))
55	    val rs1 = Input(new Bundle {
56	      val valid = Bool()
57	      val data  = UInt(32.W)
58	    })
59	    val rs2 = Input(new Bundle {
60	      val valid = Bool()
61	      val data  = UInt(32.W)
62	    })
63	    val rd = Valid(new Bundle {
64	      val addr = UInt(addrWidth.W)
65	      val data = UInt(32.W)
66	    })
67	  })
68	
69	  // Pipeline register
70	  val rdValid   = RegInit(false.B)
71	  val rdAddr    = RegInit(0.U(addrWidth.W))
72	  val rdData    = RegInit(0.U(32.W))
73	
74	  // Default: not valid
75	  rdValid := false.B
76	
77	  when(io.req.valid) {
78	    val rs1 = io.rs1.data
79	    val rs2 = io.rs2.data
80	
81	    rdAddr  := io.req.bits.addr
82	    rdValid := true.B
83	
84	    val result = Wire(UInt(32.W))
85	    result := 0.U
86	
87	    switch(io.req.bits.op) {
88	      // ---- Bitmanip ----
89	      is(AluOp.SEXTB) {
90	        result := Cat(Fill(24, rs1(7)), rs1(7, 0))
91	      }
92	      is(AluOp.SEXTH) {
93	        result := Cat(Fill(16, rs1(15)), rs1(15, 0))
94	      }
95	      is(AluOp.ZEXTH) {
96	        result := Cat(0.U(16.W), rs1(15, 0))
97	      }
98	      is(AluOp.CLZ) {
99	        // Count leading zeros of rs1 (32-bit)
100	        val clzResult = Wire(UInt(6.W))
101	        clzResult := 32.U
102	        for (i <- 0 until 32) {
103	          when(rs1(31 - i)) {
104	            clzResult := i.U
105	          }
106	        }
107	        result := clzResult
108	      }
109	      is(AluOp.CTZ) {
110	        val ctzResult = Wire(UInt(6.W))
111	        ctzResult := 32.U
112	        for (i <- (31) to 0 by -1) {
113	          when(rs1(i)) {
114	            ctzResult := i.U
115	          }
116	        }
117	        result := ctzResult
118	      }
119	      is(AluOp.CPOP) {
120	        val bits = (0 until 32).map(i => rs1(i).asUInt)
121	        result := bits.reduce(_ +& _)
122	      }
123	      is(AluOp.ORCB) {
124	        // Set each byte to 0xFF if any bit in that byte is set, else 0x00
125	        result := Cat(
126	          Mux(rs1(31, 24) =/= 0.U, 0xFF.U(8.W), 0x00.U(8.W)),
127	          Mux(rs1(23, 16) =/= 0.U, 0xFF.U(8.W), 0x00.U(8.W)),
128	          Mux(rs1(15,  8) =/= 0.U, 0xFF.U(8.W), 0x00.U(8.W)),
129	          Mux(rs1( 7,  0) =/= 0.U, 0xFF.U(8.W), 0x00.U(8.W))
130	        )
131	      }
132	      is(AluOp.REV8) {
133	        // Reverse bytes
134	        result := Cat(rs1(7, 0), rs1(15, 8), rs1(23, 16), rs1(31, 24))
135	      }
136	      is(AluOp.XNOR) {
137	        result := ~(rs1 ^ rs2)
138	      }
139	      is(AluOp.ORN) {
140	        result := rs1 | (~rs2)
141	      }
142	      is(AluOp.ANDN) {
143	        result := rs1 & (~rs2)
144	      }
145	      is(AluOp.MAX) {
146	        result := Mux(rs1.asSInt > rs2.asSInt, rs1, rs2)
147	      }
148	      is(AluOp.MAXU) {
149	        result := Mux(rs1 > rs2, rs1, rs2)
150	      }
151	      is(AluOp.MIN) {
152	        result := Mux(rs1.asSInt < rs2.asSInt, rs1, rs2)
153	      }
154	      is(AluOp.MINU) {
155	        result := Mux(rs1 < rs2, rs1, rs2)
156	      }
157	      is(AluOp.ROL) {
158	        val shamt = rs2(4, 0)
159	        result := (rs1 << shamt) | (rs1 >> (32.U - shamt))
160	      }
161	      is(AluOp.ROR) {
162	        val shamt = rs2(4, 0)
163	        result := (rs1 >> shamt) | (rs1 << (32.U - shamt))
164	      }
165	      is(AluOp.RORI) {
166	        val shamt = rs2(4, 0)
167	        result := (rs1 >> shamt) | (rs1 << (32.U - shamt))
168	      }
169	      // ---- Standard RV32I ----
170	      is(AluOp.ADD, AluOp.ADDI) {
171	        result := rs1 + rs2
172	      }
173	      is(AluOp.SUB) {
174	        result := rs1 - rs2
175	      }
176	      is(AluOp.AND, AluOp.ANDI) {
177	        result := rs1 & rs2
178	      }
179	      is(AluOp.OR, AluOp.ORI) {
180	        result := rs1 | rs2
181	      }
182	      is(AluOp.XOR, AluOp.XORI) {
183	        result := rs1 ^ rs2
184	      }
185	      is(AluOp.SLL, AluOp.SLLI) {
186	        result := rs1 << rs2(4, 0)
187	      }
188	      is(AluOp.SRL, AluOp.SRLI) {
189	        result := rs1 >> rs2(4, 0)
190	      }
191	      is(AluOp.SRA, AluOp.SRAI) {
192	        result := (rs1.asSInt >> rs2(4, 0)).asUInt
193	      }
194	      is(AluOp.SLT, AluOp.SLTI) {
195	        result := (rs1.asSInt < rs2.asSInt).asUInt
196	      }
197	      is(AluOp.SLTU, AluOp.SLTIU) {
198	        result := (rs1 < rs2).asUInt
199	      }
200	      is(AluOp.LUI) {
201	        result := rs2  // immediate passed in rs2
202	      }
203	      is(AluOp.AUIPC) {
204	        result := rs1 + rs2
205	      }
206	    }
207	
208	    rdData := result
209	  }
